// Clear all cache keys containing commit
try {
    $stmt = $pdo->query("SELECT setting_key, setting_value FROM system_settings WHERE setting_value LIKE '%commit-%'");
    $rows = $stmt->fetchAll();
    foreach ($rows as $r) {
        if (strpos($r['setting_value'], 'commit-') !== false && (strpos($r['setting_key'], 'update') !== false || strpos($r['setting_key'], 'version') !== false)) {
            echo "⚠️ Found old commit in {$r['setting_key']}: ".substr($r['setting_value'],0,100)."\n";
